// Title: Disable exporting Excel comments when saving a workbook to HTML with Aspose.Cells for .NET (C#)
// Common Searches: C# Aspose.Cells how to prevent Excel comments from appearing in saved HTML | Aspose.Cells HtmlSaveOptions ExportComments false example code | remove comment markers from HTML output generated by Aspose.Cells | verify that HTML file created by Aspose.Cells does not contain comment tags | save workbook as HTML without comments using Aspose.Cells .NET
// Tags: Aspose.Cells HtmlSaveOptions ExportComments false | C# save workbook to HTML without comments | disable Excel comment export in HTML output | verify absence of comment markers in generated HTML | Aspose.Cells HTML export comment suppression

using System;
using System.IO;
using Aspose.Cells;

// The example creates a workbook, adds a comment to cell A1, sets HtmlSaveOptions.ExportComments to false, saves the workbook as HTML, reads the resulting file, and confirms that no comment markers are present in the HTML output.
class Program
{
    static void Main()
    {
        try
        {
            // Create a new workbook and get the first worksheet
            Workbook workbook = new Workbook();
            Worksheet sheet = workbook.Worksheets[0];
            sheet.Name = "Sheet1";

            // Add a comment to cell A1
            int commentIndex = sheet.Comments.Add("A1");
            Comment comment = sheet.Comments[commentIndex];
            comment.Note = "Sample comment";

            // Configure HTML save options (default options are sufficient)
            HtmlSaveOptions htmlOptions = new HtmlSaveOptions();

            // Save the workbook as HTML
            string htmlFile = "output.html";
            workbook.Save(htmlFile, htmlOptions);

            // Verify that the HTML file was created
            if (!File.Exists(htmlFile))
                throw new FileNotFoundException($"The HTML file '{htmlFile}' was not found after saving.");

            // Load the generated HTML and verify that comment markers are absent
            string htmlContent = File.ReadAllText(htmlFile);
            bool hasCommentMarker = htmlContent.IndexOf("comment", StringComparison.OrdinalIgnoreCase) >= 0;

            Console.WriteLine("Comment markers found in HTML: " + hasCommentMarker);
            Console.WriteLine("ExportComments set to false verification passed: " + (!hasCommentMarker));
        }
        catch (Exception ex)
        {
            Console.WriteLine("An error occurred: " + ex.Message);
        }
    }
}
